User query:
Could you list the job categories for Boston? Also, calculate the average salary for “DevOps engineer” positions in San Francisco, and export the job data for IDs 1010 and 1111 in JSON format.

rewrite1:
{
  "entities": [
    {
      "type": "JobCategory",
      "filters": {
        "location": "Boston"
      },
      "operation": "list"
    },
    {
      "type": "JobListing",
      "filters": {
        "title": "DevOps engineer",
        "location": "San Francisco"
      },
      "operation": "retrieve",
      "postProcessing": {
        "aggregate": "average",
        "field": "salary",
        "outputName": "averageSalaryDevOpsSF"
      }
    },
    {
      "type": "JobDataExport",
      "identifiers": [1010, 1111],
      "format": "JSON",
      "operation": "export"
    }
  ],
  "executionPlan": [
    "Call job category service with location='Boston' to obtain list of categories.",
    "Call job listing service with title='DevOps engineer' and location='San Francisco' to retrieve all matching records.",
    "Compute the average of the 'salary' field from the retrieved DevOps engineer listings.",
    "Call job export service with job IDs [1010, 1111] and format='JSON' to obtain the export payload."
  ],
  "notes": "The job listing service may need to be invoked multiple times if pagination is required."
}

