Please retrieve the CPC (Cooperative Patent Classification) codes for patents EP4000010, EP4000020, EP4000030, EP4000040, and EP4000050, map each CPC code to its appropriate technology domain, and provide a concise summary showing how many patents fall into each domain. Ensure the CPC data retrieval is performed concurrently before the mapping and summarization steps.

rewrite1:
{
  "operation": "pipeline",
  "steps": [
    {
      "action": "retrieveCpcCodes",
      "parameters": {
        "patentIds": [
          "EP4000010",
          "EP4000020",
          "EP4000030",
          "EP4000040",
          "EP4000050"
        ],
        "concurrent": true
      },
      "outputKey": "cpcData"
    },
    {
      "action": "mapCpcToTechnologyDomain",
      "parameters": {
        "cpcCodes": "${cpcData}",
        "mappingReference": "CPC_TechnologyDomain"
      },
      "outputKey": "domainMapping"
    },
    {
      "action": "aggregateDomainCounts",
      "parameters": {
        "mappedDomains": "${domainMapping}",
        "aggregation": "count"
      },
      "outputKey": "domainSummary"
    }
  ],
  "finalOutput": "domainSummary"
}

